insert into public.datapoints_taxonomia
  (codigo, marco, norma, pilar, seccion_indice, estandar, edicion, descripcion, pagina_origen, version_taxonomia)
values
  ('GRI 2-1', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar su nombre legal; b. indicar la naturaleza de la propiedad y su forma jurídica; c. indicar la ubicación de su sede central; d. indicar en qué países opera.', 8, '2025'),
  ('GRI 2-2', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. enumerar todas sus entidades incluidas en la presentación de informes de sostenibilidad; b. si la organización tiene estados financieros consolidados y auditados o información financiera archivada en registros públicos, especificar las diferencias existentes entre la lista de entidades incluida en sus informes financieros y la de sus informes de sostenibilidad; c. si la organización se compone de varias entidades, explicar el enfoque adoptado para consolidar la información, incluido: i. si el enfoque supone ajustes de la información para participaciones minoritarias; ii. qué enfoque adoptó ante fusiones, adquisiciones y escisiones de entidades o partes de dichas entidades; iii. si el enfoque cambia y cómo, en los distintos contenidos de este Estándar y en los diferentes temas materiales.', 9, '2025'),
  ('GRI 2-3', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. especificar el periodo objeto del informe y la frecuencia de sus informes de sostenibilidad; b. especificar el periodo objeto de sus informes financieros y, en caso de que no se alinee con el periodo objeto de los informes de sostenibilidad, explicar la razón; c. indicar la fecha de publicación del informe o de la información presentada; d. especificar el punto de contacto para cuestiones relacionadas con el informe o la información presentada.', 10, '2025'),
  ('GRI 2-4', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar actualizaciones de la información presentada en periodos objeto de informes anteriores y explicar: i. los motivos de las actualizaciones; ii. el efecto de las actualizaciones.', 11, '2025'),
  ('GRI 2-5', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir su política y su práctica de solicitud de verificación externa e indicar si el máximo órgano de de gobierno y los altos ejecutivos participan y, de ser así, de qué manera; b. si la presentación de informes de sostenibilidad de la organización se ha sometido a verificación externa: i. facilitar un enlace o referencia al informe de verificación externa o a la declaración de verificación; ii. describir qué se ha verificado y en base a qué e indicar los estándares de verificación utilizados, el nivel de verificación obtenido y cualquier limitación del proceso de verificación; iii. describir la relación existente entre la organización y el proveedor de la verificación.', 12, '2025'),
  ('GRI 2-6', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar el sector o los sectores en los que tiene actividad; b. describir su cadena de valor, lo que incluye: i. las actividades, los productos y los servicios de la organización, y los mercados atendidos; ii. la cadena de suministro de la organización; iii. las entidades aguas abajo de la organización y sus actividades; c. indicar otras relaciones comerciales pertinentes; d. describir los cambios significativos en 2-6-a, 2-6-b y 2-6-c con respecto al periodo objeto del informe.', 13, '2025'),
  ('GRI 2-7', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar el número total de empleados, y desglosarlo por género y región; b. indicar el número total de: i. empleados fijos, y desglosarlo por género y región; ii. empleados temporales, y desglosarlo por género y región; iii. empleados por horas no garantizadas, y desglosarlo por género y región; iv. empleados a tiempo completo, y desglosarlo por género y región; v. empleados a tiempo parcial, y desglosarlo por género y región; c. describir los métodos y las suposiciones empleados para compilar los datos y si se presentan las cifras: i. como plantilla de personal, unidades equivalentes de tiempo completo u otra metodología; ii. al final del periodo objeto del informe, como media de todo el periodo objeto del informe o con otra metodología; d. presentar la información de contexto necesaria para entender los datos presentados en 2-7-a y 2-7-b; e. describir fluctuaciones significativas del número de empleados durante el periodo objeto del informe y entre distintos periodos objeto de los informes.', 15, '2025'),
  ('GRI 2-8', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar el número total de: trabajadores que no son empleados y cuyo trabajo es controlado por la organización y describir: i. los tipos de trabajadores más habituales y su relación contractual con la organización; ii. el tipo de trabajo que realizan; b. describir los métodos y las suposiciones empleados para compilar los datos y si se presenta el número de trabajadores que no son empleados: i. como plantilla de personal, unidades equivalentes de tiempo completo u otra metodología; ii. al final del periodo objeto del informe, como media de todo el periodo objeto del informe o con otra metodología; c. describir fluctuaciones significativas del número de trabajadores que no son empleados durante el periodo objeto del informe y entre distintos periodos objeto de los informes.', 18, '2025'),
  ('GRI 2-9', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir su estructura de gobernanza, incluidos los comités del máximo órgano de gobierno; b. enumerar los comités del máximo órgano de gobierno encargados de la toma de decisiones y de la supervisión de la gestión de los impactos de la organización sobre la economía, el medio ambiente y las personas; c. describir la composición del máximo órgano de gobierno y sus comités según: i. el número de miembros ejecutivos y no ejecutivos; ii. independencia; iii. la antigüedad de los miembros en el órgano de gobierno; iv. el número de otros cargos y compromisos significativos de cada miembro y la naturaleza de los compromisos; v. género; vi. los grupos sociales infrarrepresentados; vii. las competencias relevantes para los impactos de la organización; viii. la representación de los grupos de interés.', 20, '2025'),
  ('GRI 2-10', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir los procesos de designación y selección del máximo órgano de gobierno y sus comités; b. describir los criterios empleados para designar y seleccionar a los miembros del máximo órgano de gobierno e indicar si se tiene en cuenta lo siguiente y cómo: i. opiniones de los grupos de interés (incluidos los accionistas); ii. diversidad; iii. independencia; iv. competencias pertinentes para los impactos de la organización.', 22, '2025'),
  ('GRI 2-11', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar si el presidente del máximo órgano de gobierno es también un alto ejecutivo de la organización; b. si el presidente también es un alto ejecutivo, explicar su función dentro de la gerencia de la organización, las razones de esta configuración y cómo se evitan y mitigan los conflictos de interés.', 23, '2025'),
  ('GRI 2-12', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir la función que desempeñan el máximo órgano de gobierno y los altos ejecutivos en el desarrollo, la aprobación y la actualización del propósito de la organización, las declaraciones de valores o misión, las estrategias, las políticas y los objetivos relacionados con el desarrollo sostenible; b. describir la función que desempeña el máximo órgano de gobierno en la supervisión de la debida diligencia de la organización y de otros procesos para identificar y abordar sus impactos sobre la economía, el medio ambiente y las personas, entre ellos: i. si el máximo órgano de gobierno se involucra en la participación de los grupos de interés en este proceso y, de ser así, de qué manera; ii. cómo considera el máximo órgano de gobierno los resultados de estos procesos; c. describir la función que desempeña el máximo órgano de gobierno en la revisión de la eficacia de los procesos de la organización, según lo descrito en 2-12-b, e indicar la frecuencia de estas revisiones.', 24, '2025'),
  ('GRI 2-13', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir cómo delega el máximo órgano de gobierno la responsabilidad de gestionar los impactos de la organización sobre la economía, el medio ambiente y las personas, incluido: i. si ha designado a algún alto ejecutivo con responsabilidad para la gestión de los impactos; ii. si ha delegado la responsabilidad de gestión de los impactos sobre otros empleados; b. describir los procesos y la frecuencia con la que los altos ejecutivos y otros empleados informan al máximo órgano de gobierno sobre la gestión de los impactos de la organización sobre la economía, el medio ambiente y las personas.', 25, '2025'),
  ('GRI 2-14', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar si el máximo órgano de gobierno tiene la responsabilidad de revisar y aprobar la información presentada, incluidos los temas materiales de la organización y, de ser así, describir el proceso de revisión y aprobación de la información; b. indicar si el máximo órgano de gobierno no tiene la responsabilidad de revisar y aprobar la información presentada, incluidos los temas materiales de la organización y, de ser así, explicar la razón.', 26, '2025'),
  ('GRI 2-15', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir los procesos para que el máximo órgano de gobierno asegure que los conflictos de interés se previenen y se mitigan; b. indicar si se informa de los conflictos de interés a los grupos de interés, incluidos, como mínimo, los conflictos de interés relativos a: i. la pertenencia a distintos consejos directivos; ii. la participación accionarial cruzada con proveedores y otros grupos de interés; iii. la existencia de accionistas controladores; iv. las partes relacionadas, sus relaciones, transacciones y saldos pendientes.', 27, '2025'),
  ('GRI 2-16', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir si se comunican las inquietudes críticas al máximo órgano de gobierno y, de ser así, de qué manera; b. indicar el número total y la naturaleza de las inquietudes críticas comunicadas al máximo órgano de gobierno durante el periodo objeto del informe.', 28, '2025'),
  ('GRI 2-17', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar información sobre las medidas adoptadas para incrementar los conocimientos, las habilidades y la experiencia colectivos del máximo órgano de gobierno en materia de desarrollo sostenible.', 29, '2025'),
  ('GRI 2-18', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir los procesos de evaluación del desempeño del máximo órgano de gobierno en lo relativo a la supervisión de la gestión de los impactos de la organización sobre la economía, el medio ambiente y las personas; b. indicar si las evaluaciones son independientes y la frecuencia con que se realizan; c. describir las medidas adoptadas en respuesta a las evaluaciones, incluidos los cambios en la composición del máximo órgano de gobierno y en las prácticas organizativas.', 30, '2025'),
  ('GRI 2-19', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir las políticas de remuneración de los miembros del máximo órgano de gobierno y de los altos ejecutivos, lo que incluye: i. remuneración fija y variable; ii. bonos de contratación o pagos de incentivos por la contratación; iii. indemnizaciones por rescisión del contrato; iv. reembolsos; v. prestaciones de jubilación; b. describir cómo se vinculan las políticas de remuneración de los miembros del máximo órgano de gobierno y de los altos ejecutivos con sus objetivos y su desempeño en la gestión de los impactos de la organización sobre la economía, el medio ambiente y las personas.', 31, '2025'),
  ('GRI 2-20', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir el proceso de diseño de sus políticas de remuneración y de determinación de la remuneración, lo que incluye: i. si miembros independientes del máximo órgano de gobierno o un comité de remuneraciones independiente supervisan el proceso de determinación de la remuneración; ii. cómo se solicita y se toma en cuenta la opinión de los grupos de interés (incluidos los accionistas) para determinar la remuneración; iii. si participan consultores especialistas en remuneraciones en la determinación de la remuneración y, de ser así, si son independientes de la organización, su máximo órgano de gobierno y sus altos ejecutivos; b. presentar información sobre el resultado de los votos de los grupos de interés (incluidos los accionistas) en relación a las políticas y las propuestas de remuneración, si procede.', 32, '2025'),
  ('GRI 2-21', 'GRI', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar el ratio de compensación total anual de la persona mejor pagada de la organización con respecto a la mediana de la compensación total anual de todos los empleados (excluida la persona mejor pagada); b. presentar el ratio del porcentaje de incremento de la compensación total anual de la persona mejor pagada de la organización con respecto a la mediana del porcentaje de incremento de la compensación total anual de todos los empleados (excluida la persona mejor pagada); c. presentar la información contextual necesaria para entender los datos y cómo se han recopilado.', 33, '2025'),
  ('GRI 2-22', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar una declaración del máximo órgano de gobierno o el más alto ejecutivo de la organización sobre la importancia del desarrollo sostenible para la organización y su estrategia de contribución a este.', 35, '2025'),
  ('GRI 2-23', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir sus compromisos y políticas de conducta empresarial responsable, lo que incluye: i. los instrumentos intergubernamentales a los que los compromisos hacen referencia; ii. si los compromisos estipulan la realización de una debida diligencia; iii. si los compromisos estipulan la aplicación del principio precautorio; iv. si los compromisos estipulan el respeto de los derechos humanos; b. describir sus compromisos y políticas específicas para el respeto de los derechos humanos, lo que incluye: i. los derechos humanos reconocidos internacionalmente que el compromiso contempla; ii. las categorías de grupos de interés, incluidos los grupos de riesgo o los grupos vulnerables, a los que la organización presta especial atención en el compromiso; c. proporcionar enlaces a los compromisos y políticas si son de acceso público o, si los compromisos y políticas no están disponibles para el público, explicar la razón; d. indicar el nivel al que se aprobó cada uno de los compromisos y políticas dentro de la organización, y si se trata del máximo nivel; e. indicar la medida en que los compromisos y políticas son de aplicación a las actividades de la organización y a sus relaciones comerciales; f. describir cómo se comunican los compromisos y políticas a trabajadores, socios comerciales, y otras partes pertinentes.', 36, '2025'),
  ('GRI 2-24', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir cómo incorpora cada uno de sus compromisos o políticas para una conducta empresarial responsable en todas sus actividades y relaciones comerciales, lo que incluye: i. cómo asigna responsabilidades para aplicar los compromisos en los diferentes niveles de la organización; ii. cómo integra los compromisos en las estrategias organizativas y las políticas y los procedimientos operativos; iii. cómo aplica sus compromisos con sus relaciones comerciales y a través de ellas; iv. la formación sobre la aplicación de los compromisos que imparte la organización.', 39, '2025'),
  ('GRI 2-25', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir sus compromisos para proporcionar o colaborar en la remediación de los impactos negativos que la organización reconoce que ha ocasionado o a los que ha contribuido; b. describir su enfoque para identificar y abordar las reclamaciones, incluidos los mecanismos de quejas y reclamación que ha instaurado o en los que participa; c. describir otros procesos mediante los que proporciona o colabora en la remediación de los impactos negativos que la organización reconoce que ha ocasionado o a los que ha contribuido; d. describir cómo se cuenta con la participación de los grupos de interés que son los usuarios previstos de los mecanismos de quejas y reclamación para el diseño, la revisión, la operación y la mejora de estos mecanismos; e. describir cómo hace la organización un seguimiento de la eficacia de los mecanismos de quejas y reclamación y de otros procesos de remediación y presentar ejemplos de su eficacia, con la retroalimentación de los grupos de interés.', 41, '2025'),
  ('GRI 2-26', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir los mecanismos para que los individuos: i. soliciten asesoramiento sobre la aplicación de las políticas y prácticas de la organización para una conducta empresarial responsable; ii. planteen sus inquietudes sobre la conducta empresarial de la organización.', 44, '2025'),
  ('GRI 2-27', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar información sobre el número total de casos de incumplimiento significativos de la legislación y las normativas durante el periodo objeto del informe, y un desglose de este total por: i. casos que derivaron en multas; ii. casos que derivaron en sanciones no monetarias; b. informar el número total y el valor monetario de las multas que se pagaron durante el periodo objeto del informe por el incumplimiento de la legislación y las normativas, y desglosado por: i. multas por casos de incumplimiento de la legislación y las normativas que se hayan producido durante el periodo objeto del informe; ii. multas por casos de incumplimiento de la legislación y las normativas que se hayan producido en informes anteriores; c. describir los casos de incumplimiento significativos; d. describir cómo ha determinado los casos de incumplimiento significativos.', 45, '2025'),
  ('GRI 2-28', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. presentar información sobre asociaciones del sector, otras afiliaciones a asociaciones y organizaciones nacionales o internacionales de defensa de intereses en las que tiene un papel significativo.', 47, '2025'),
  ('GRI 2-29', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. describir su enfoque para contar con la participación de los grupos de interés, incluido: i. las categorías de grupos de interés con las que se involucra y cómo las identifica; ii. el propósito de la participación de los grupos de interés; iii. cómo la organización busca asegurar que la participación de los grupos de interés resulte provechosa.', 48, '2025'),
  ('GRI 2-30', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 2', '2021', 'La organización debe: a. indicar el porcentaje total de empleados cubiertos por los convenios de negociación colectiva ; b. para los empleados que no estén cubiertos por los convenios de negociación colectiva, indicar si la organización determina sus condiciones laborales y los términos de su empleo en función de los convenios de negociación colectiva que cubren al resto de los empleados o en función de los convenios de negociación colectiva de otras organizaciones.', 50, '2025'),
  ('GRI 3-1', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 3', '2021', 'La organización debe: a. describir el proceso que ha seguido para determinar sus temas materiales, incluido: i. cómo ha identificado sus impactos reales y potenciales, negativos y positivos, sobre la economía, el medio ambiente y las personas, incluidos los impactos sobre los derechos humanos, en todas sus actividades y relaciones comerciales; ii. cómo ha priorizado los impactos sobre los que informar en función de su importancia; b. especificar los grupos de interés y expertos cuyos puntos de vista han participado en el proceso de determinación de sus temas materiales.', 18, '2025'),
  ('GRI 3-2', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 3', '2021', 'La organización debe: a. enumerar sus temas materiales; b. informar de los cambios que se hayan producido en la lista de temas materiales con respecto al periodo objeto del informe anterior.', 20, '2025'),
  ('GRI 3-3', 'GRI', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'GRI 3', '2021', 'Para cada tema material del que se presente información en el Contenido 3-2, la organización debe: a. describir los impactos reales y potenciales, negativos y positivos, sobre la economía, el medio ambiente y las personas, incluidos los impactos sobre los derechos humanos; b. indicar si la organización está relacionada con un impacto negativo mediante sus actividades o como resultado de sus relaciones comerciales, y describir las actividades o relaciones comerciales; c. describir sus políticas o compromisos en relación al tema material; d. describir las medidas adoptadas para gestionar el tema y los impactos asociados, lo que incluye: i. las medidas adoptadas para prevenir o mitigar impactos negativos potenciales; ii. las medidas adoptadas para abordar los impactos negativos potenciales, incluidas las medidas para facilitar o colaborar en su remediación; iii. las medidas adoptadas para gestionar los impactos negativos reales y potenciales; e. presentar la siguiente información sobre el seguimiento de la eficacia de las medidas adoptadas: i. procesos usados para hacer un seguimiento de la eficacia de las medidas; ii. metas, objetivos e indicadores usados para evaluar el progreso; iii. la eficacia de las medidas, incluido el avance hacia la consecución de las metas y los objetivos; iv. lecciones aprendidas y cómo se han incorporado a las políticas y los procedimientos operativos de la organización; f. describir cómo la participación de los grupos de interés ha influido en las medidas adoptadas (3-3-d) y cómo ha informado si estas han sido efectivas (3-3-e).', 21, '2025'),
  ('FN-CB-000.A', 'SASB', 'S2'::public.norma_niif, 'metricas'::public.pilar_niif, 'Activity Metrics', 'SASB FN-CB', '2025-12', '(1) Number and (2) value of checking and savings accounts by segment: (a) personal and (b) small business', 7, '2025'),
  ('FN-CB-000.B', 'SASB', 'S2'::public.norma_niif, 'metricas'::public.pilar_niif, 'Activity Metrics', 'SASB FN-CB', '2025-12', '(1) Number and (2) value of loans by segment: (a) personal, (b) small business, and (c) corporate', 7, '2025'),
  ('FN-CB-230a.1', 'SASB', 'S2'::public.norma_niif, 'metricas'::public.pilar_niif, 'Data Security', 'SASB FN-CB', '2025-12', '(1) Number of data breaches, (2) percentage that are personal data breaches, (3) number of account holders affected', 8, '2025'),
